const updateLadoTaskPart = `-- name: UpdateLadoTaskPart :execrows
UPDATE lado_task_parts
SET state = ?1,
    attempts = ?2,
    merge_attempts = ?3,
    waiting_reason = ?4,
    waiting_detail = ?5,
    session_id = ?6,
    branch = ?7,
    start_sha = ?8,
    merge_from_sha = ?9,
    merge_tip_sha = ?10,
    merged_sha = ?11,
    merge_session_id = ?12,
    merge_branch = ?13,
    summary = ?14,
    error_message = ?15,
    updated_at = ?16
WHERE lado_task_parts.queue_entry_id = ?17
  AND lado_task_parts.part_id = ?18
  AND lado_task_parts.state = ?19
`

type UpdateLadoTaskPartParams struct {
	State          string
	Attempts       int64
	MergeAttempts  int64
	WaitingReason  string
	WaitingDetail  string
	SessionID      string
	Branch         string
	StartSha       string
	MergeFromSha   string
	MergeTipSha    string
	MergedSha      string
	MergeSessionID string
	MergeBranch    string
	Summary        string
	ErrorMessage   string
	UpdatedAt      time.Time
	QueueEntryID   string
	PartID         string
	OldState       string
}

// Writes a part's progress. The caller read the row and passes its state as
// old_state, so a write from a stale read changes nothing.
func (q *Queries) UpdateLadoTaskPart(ctx context.Context, arg UpdateLadoTaskPartParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateLadoTaskPart,
		arg.State,
		arg.Attempts,
		arg.MergeAttempts,
		arg.WaitingReason,
		arg.WaitingDetail,
		arg.SessionID,
		arg.Branch,
		arg.StartSha,
		arg.MergeFromSha,
		arg.MergeTipSha,
		arg.MergedSha,
		arg.MergeSessionID,
		arg.MergeBranch,
		arg.Summary,
		arg.ErrorMessage,
		arg.UpdatedAt,
		arg.QueueEntryID,
		arg.PartID,
		arg.OldState,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
